public List<Integer> rotateLeft(int d, List<Integer> a) {
    int n = a.size();
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = a.get(i);
    }
    for (int r = 0; r < d; r++) {
        int first = arr[0];
        for (int i = 1; i < n; i++) {
            arr[i - 1] = arr[i];
        }
        arr[n - 1] = first;
    }
    List<Integer> result = new ArrayList<>(n);
    for (int v : arr) {
        result.add(v);
    }
    return result;
}

