def rotateLeft(self, d: int, a: list[int]) -> list[int]:
    arr = a[:]
    n = len(arr)
    for _ in range(d):
        first = arr[0]
        for i in range(1, n):
            arr[i - 1] = arr[i]
        arr[n - 1] = first
    return arr

