public List<Integer> rotateLeft(int d, List<Integer> a) {
    int n = a.size();
    d %= n;
    List<Integer> result = new ArrayList<>(Collections.nCopies(n, 0));
    for (int i = 0; i < n; i++) {
        result.set(i, a.get((i + d) % n));
    }
    return result;
}

public List<Integer> rotateLeft(int d, List<Integer> a) {
    int n = a.size();
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = a.get(i);
    }
    d %= n;
    reverse(arr, 0, d - 1);
    reverse(arr, d, n - 1);
    reverse(arr, 0, n - 1);
    List<Integer> result = new ArrayList<>(n);
    for (int v : arr) {
        result.add(v);
    }
    return result;
}

private void reverse(int[] arr, int lo, int hi) {
    while (lo < hi) {
        int tmp = arr[lo];
        arr[lo] = arr[hi];
        arr[hi] = tmp;
        lo++;
        hi--;
    }
}

